1063	    \begin{lemma}\label{lem:qld-sublines}
1064	      There exists a distribution $D$ over tuples $(\line, \line_X, \line_Z)$ with the following properties:
1065	      \begin{enumerate}
1066	      \item The marginal distribution over $\line$ is the same as the marginal of the line-point distribution over $\F_q^{2m+2}$.
1067	\item For any point of the form $u = (u_X, u_Z, \alpha, \beta)$ lying on $\line$, it holds that $u_X \in \line_X$ and $u_Z \in \line_Z$. Moreover, for $u$ chosen uniformly at random in $\line$ the marginal distribution over $(\line_X,\line_Z, u_X)$ (resp.\ over $(\line_X,\line_Z, u_Z)$) is such that the marginal over $(\ell_X,\ell_Z)$ is a mixture of $D_{\ALine, i}\times D_{\ALine, j}$ and $D_{\DLine, i}\times D_{\DLine, j}$ for $i,j\in\{1,\ldots,m\}$ and moreover, conditioned on $(\ell_X,\ell_Z)$, $u_X$ is uniformly random on $\line_X$ (resp. $u_Z$ uniformly random on $\line_Z$). 
1068	\end{enumerate}
1069	    \end{lemma}
1070			
1071	    \begin{proof}
1072	      We describe $D$ by giving a procedure to sample from it. We start by sampling $(\line, u)$ from the line-point distribution over $\F_q^{2m+2}$. Write $u = (u_X, u_Z, \alpha, \beta)$. 
1073		There are two cases to consider: the case where $\line$ is
1074	        axis-parallel and the case where $\line$ is diagonal. In each case, we sample lines $\line_\xpt$ and $\line_\zpt$ such that the tuples  $(\line_\xpt,
1075	        \line_\zpt,u_\xpt)$ and $(\line_\xpt, \line_\zpt,u_\zpt)$ satisfy Property~2 of the lemma.
1076	        \begin{enumerate}
1077	          \item Suppose $\line$ is an  axis-parallel line $(v,e_j)$ where
1078	            $v = (v_\xpt,v_\zpt,\alpha_0,\beta_0)$. Then we sample $(v'_\xpt, i_\xpt), (v'_\zpt, i_\zpt) \in \F_q^m \times \{1,2, \ldots, m\}$ as described below, and set $\line_\xpt =
1079	            (v'_\xpt,e_{i_\xpt}),\line_\zpt = (v'_\zpt, e_{i_\zpt})$.
1080	            \begin{enumerate}
1081	              \item If $1 \leq j \leq m$, then set $i_\xpt = j$ and
1082	                choose $i_\zpt$ to be uniformly random in $\{1, \dots,
1083	                m\}$.
1084	              \item If  $m+1 \leq j \leq 2m$, then set $i_\xpt$ to be
1085	                uniformly random in $\{1, \dots, m\}$ and $i_\zpt = j - m$.
1086	              \item If $2m + 1 \leq j \leq 2m+2$, then set $i_\xpt$
1087	                and $i_\zpt$ to both be uniformly random in $\{1, \dots, m\}$.
1088	              \item Let $v'_\xpt$ be the canonical representative
1089	                $L_{e_{i_\xpt}}^\lnf(v_\xpt)$, and
1090	                likewise let $v'_\zpt$ be the canonical
1091	                representative $L_{e_{i_\zpt}}^\lnf(v_{\zpt})$ (see
1092	                \Cref{def:line-representative} for the definition of
1093	                the canonical representative of a line). Note that
1094	                $v_\xpt$ lies on the line $\line_\xpt = (v'_\xpt,
1095	                e_{i_\xpt})$, and similarly for $v_\zpt$ and
1096	                $\line_{\zpt} = (v'_\zpt, e_{i_\zpt})$.
1097	              \end{enumerate}
1098	              We claim that this construction satisfies Property~2 of the lemma. We show this first $(\line_X,\line_Z)$ and $u_X$, the other case being symmetric. If we are in case (a), then $u_X$ is a uniformly random point on the line $\line_X=(v_X, e_j)$ and $\line_Z=(v_Z,e_{i_Z})$, which is independent from $\line_X$. Thus, the marginal distribution over $(\line_X,u_X)$ conditioned on $j$ in this case is equal to $D_{\ALine, j}$ and furthermore even conditioned on $(\line_X,u_X)$, $\line_Z$ is distributed according to $D_{\ALine,i_Z}$ for a uniformly random $i_Z$. Cases (b) and (c) are analogous except that in this case even conditioned on $j$, $i_X$ is uniform. 
1099	      \item Suppose $\ell$ is a random diagonal line $(v, s, w)$,
1100	        where $v = (v_\xpt, v_\zpt, \alpha, \beta)$, and
1101	        where $w = (w_\xpt, w_\zpt, \gamma, \delta) $ is a direction vector whose first nonzero coordinate is
1102	         $j = \chi(s)$ (where $\chi$ is defined in \Cref{eq:chi-func}). We sample $\line_\xpt =  (v'_\xpt, s_\xpt,
1103	        w'_\xpt)$ and $\line_\zpt = (v'_\zpt, s_\zpt, w'_\zpt)$ in the following
1104	        manner:
1105	        \begin{enumerate}
1106	          \item If $1 \leq j \leq m$, then $w'_\xpt = w_\xpt$ and $w'_\zpt = w_\zpt$. We choose $s_\xpt$ and $s_\zpt$ such that $\chi(s_\xpt) = j$ and $\chi(s_\zpt) = 1$.
1107	          \item If $m+1 \leq j \leq 2m$, then $w'_\xpt$ is a random
1108	            diagonal line direction (and $s_{\xpt}$ is chosen accordingly), and $w'_\zpt = w_\zpt$, with $s_\zpt$ such that $\chi(s_\zpt) = j - m$.
1109	          \item If $2m+1 \leq j \leq 2m+2$ then both $w_\xpt$, and
1110	            $w_\zpt$ are uniformly random, with $s_\xpt$ and $s_\zpt$ chosen accordingly.
1111	          \item Set $v'_\xpt = L_{w'_{\xpt}}^\lnf(v_\xpt)$ and $v'_\zpt = L_{w'_{\zpt}}^\lnf(v_\zpt)$.
1112	          \end{enumerate}
1113	          We claim that this construction satisfies Property~2 of the Lemma. We show this first $(\line_X,\line_Z)$ and $u_X$, the other case being symmetric.  If we are in case (a), then $u_X$ is a uniformly random point on the diagonal line $(v_X, s_X, w_X)$ which is equal to $\line_X$. Thus, the marginal distribution over $(\line_X, u_X)$ conditioned on $j$ in this case is equal to $D_{\DLine, j}$. Furthermore, conditioned on $(\line_X,u_X)$, $\line_Z$ is distributed according to $D_{\DLine,1}$. The other cases can be analyed analogously, with the only difference being how the indices $i,j$ of $\line_X$ and $\line_Z$ distributions are chosen. 
1114						    \end{enumerate}
1115		Let $D$ be the distribution over tuples $(\line, \line_X, \line_Z)$ induced by this procedure. This distribution $D$ satisfies Property 1 in the lemma by  construction, and Property 2 as argued above.
1116	    \end{proof}
